package com.example.Social_Media_RestApi_Project.support;

import com.example.Social_Media_RestApi_Project.comment.entity.Comment;
import com.example.Social_Media_RestApi_Project.post.entity.Post;
import com.example.Social_Media_RestApi_Project.user.entity.User;
import org.springframework.test.util.ReflectionTestUtils;

/** Builds entities with ids for unit tests (ids are normally generated by the database). */
public final class TestData {

    private TestData() {
    }

    public static User user(Long id) {
        User user = new User("User " + id, "user" + id + "@example.com", "encoded-password");
        ReflectionTestUtils.setField(user, "id", id);
        return user;
    }

    public static Post post(Long id, User author) {
        Post post = new Post(author, "Post title " + id, "Post content " + id);
        ReflectionTestUtils.setField(post, "id", id);
        return post;
    }

    public static Comment comment(Long id, User author, Post post) {
        Comment comment = new Comment("Comment " + id, author, post);
        ReflectionTestUtils.setField(comment, "id", id);
        return comment;
    }
}
